"use client";
// import { useRouter } from "next/navigation";
import React, { useEffect, useRef, useState } from "react";
import ReCAPTCHA from "react-google-recaptcha";
import { RiErrorWarningLine } from "react-icons/ri";

const ForgotPassword = () => {
  const [email, setEmail] = useState<string>("");
  const [isClient, setIsClient] = useState<boolean>(false);
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [captchaVerified, setCaptchaVerified] = useState<boolean>(false);
  const [showCaptcha, setShowCaptcha] = useState<boolean>(false);
  const [emailTouched, setEmailTouched] = useState<boolean>(false);
  const captchaContainerRef = useRef<HTMLDivElement | null>(null);
  // const router = useRouter();

  useEffect(() => {
    setIsClient(true); // Render client-side only
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        captchaContainerRef.current &&
        !captchaContainerRef.current.contains(event.target as Node)
      ) {
        setShowCaptcha(false);
      }
    };

    document.addEventListener("click", handleClickOutside);
    return () => {
      document.removeEventListener("click", handleClickOutside);
    };
  }, []);

  const handleCaptchaChange = (token: string | null) => {
    setCaptchaVerified(!!token);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setShowCaptcha(true);
  };

  const isEmailValid =
    email && /^[\w-]+(\.[\w-]+)*@([\w-]+\.)+[a-zA-Z]{2,7}$/.test(email);

  if (!isClient) return <div>Loading...</div>;

  return (
    <div className="h-screen flex flex-col items-center justify-center bg-gradient-to-r from-green-100 via-purple-100 to-purple-200">
      <div className="w-full max-w-md bg-white rounded-2xl shadow-lg p-8">
        <h2 className="text-xl font-medium text-center">Forgot Password</h2>
        <form className="space-y-4 mt-6" onSubmit={handleSubmit}>
          <div>
            <label className="block text-sm font-medium text-gray-700">
              Your Email
            </label>
            <input
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              onBlur={() => setEmailTouched(true)}
              type="email"
              placeholder="Enter your registered email"
              className="mt-1 block w-full px-5 py-2 border border-gray-200 rounded-full shadow-sm hover:border-[#1677ff] focus:border-[#1677ff] focus:ring-1 focus:ring-[#1677ff] focus:outline-none text-sm"
            />
            {emailTouched && !isEmailValid && (
              <p className="text-red-500 text-xs flex items-center gap-1">
                <RiErrorWarningLine />
                Please enter a valid email address.
              </p>
            )}
          </div>
          <button
            type="submit"
            disabled={!isEmailValid}
            className={`w-full flex items-center justify-center py-3 rounded-full text-white ${
              isEmailValid ? "bg-black" : "bg-gray-400 cursor-not-allowed"
            }`}
          >
            Continue
          </button>
        </form>
        {showCaptcha && (
          <div className="captcha-overlay">
            <ReCAPTCHA
              sitekey="NEXT_PUBLIC_RECAPTCHA_SITE_KEY"
              onChange={handleCaptchaChange}
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default ForgotPassword;
